<?php require_once __DIR__.'/../config.php';require_admin();$pageTitle='Administração';$pdo=db();$total=(int)$pdo->query('SELECT COUNT(*) FROM usuarios')->fetchColumn();$admins=(int)$pdo->query("SELECT COUNT(*) FROM usuarios WHERE tipo='administrador'")->fetchColumn();$comuns=$total-$admins;$users=$pdo->query('SELECT id,nome,email,tipo,criado_em FROM usuarios ORDER BY criado_em DESC')->fetchAll();require __DIR__.'/../includes/header.php'; ?><div class="page-top"><div><div class="eyebrow">Controle da plataforma</div><h1 class="page-title">Painel administrativo</h1></div><span class="badge redbg">ACESSO ADMINISTRADOR</span></div><div class="stats"><div class="stat"><strong><?= $total ?></strong><span>Total de contas</span></div><div class="stat"><strong><?= $admins ?></strong><span>Administradores</span></div><div class="stat"><strong><?= $comuns ?></strong><span>Usuários comuns</span></div></div><div class="section-head"><div><h2>Gerenciar baterias</h2><p>Controle as baterias do sistema, seus horários, preços e status.</p></div><a class="btn" href="baterias-nova.php">Nova bateria</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Nome</th><th>Data</th><th>Horário</th><th>Duração</th><th>Preço</th><th>Capacidade</th><th>Vagas</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php $baterias=$pdo->query('SELECT * FROM baterias ORDER BY data,horario')->fetchAll(); foreach($baterias as $b): ?><tr><td><?= e($b['nome']) ?></td><td><?= date('d/m/Y',strtotime($b['data'])) ?></td><td><?= substr($b['horario'],0,5) ?></td><td><?= (int)$b['duracao'] ?> min</td><td>R$ <?= number_format((float)$b['preco'],2,',','.') ?></td><td><?= (int)$b['total_vagas'] ?></td><td><?= (int)$b['vagas_disponiveis'] ?></td><td><span class="badge <?= $b['status']==='cancelada'||$b['status']==='encerrada'?'redbg':($b['status']==='lotada'?'dark':'green') ?>"><?= e(ucfirst($b['status'])) ?></span></td><td><div class="actions"><a class="btn small dark" href="baterias-editar.php?id=<?= (int)$b['id'] ?>">Editar</a><form class="inline-form" method="post" action="baterias.php" data-confirm="Tem certeza que deseja excluir a bateria <?= e($b['nome']) ?>?"><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="excluir"><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><button class="btn small" type="submit">Excluir</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><div class="section-head" style="margin-top:32px"><div><h2>Contas cadastradas</h2><p>Gerencie os usuários que possuem acesso ao Kart Center.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Nome</th><th>E-mail</th><th>Tipo</th><th>Cadastro</th><th>Ações</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td>#<?= (int)$u['id'] ?></td><td><?= e($u['nome']) ?></td><td><?= e($u['email']) ?></td><td><span class="badge <?= $u['tipo']==='administrador'?'redbg':'green' ?>"><?= e($u['tipo']) ?></span></td><td><?= date('d/m/Y',strtotime($u['criado_em'])) ?></td><td><div class="actions"><a class="btn small dark" href="editar-usuario.php?id=<?= (int)$u['id'] ?>">Editar</a><?php if($u['id']!=user()['id']): ?><form class="inline-form" method="post" action="excluir-usuario.php" data-confirm="Tem certeza que deseja excluir a conta de <?= e($u['nome']) ?>?"><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="btn small" type="submit">Excluir</button></form><?php else: ?><span class="muted" style="font-size:11px">Sua conta</span><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__.'/../includes/footer.php'; ?>
